1	package tariff
2	
3	import (
4		"errors"
5		"testing"
6		"time"
7	)
8	
9	// 旧版本被替代后，后续登记的重叠判断必须依据各版本的“实际有效区间”，
10	// 不能继续把旧版本登记时填写的结束时间当成占用期限。这是该既有行为的回归测试。
11	//
12	// 时间线（UTC，结束时刻均不含）：
13	//
14	//	旧版本 seat-v1：单价 150 分，2026-03-01 00:00 生效，登记结束 2026-03-31 00:00
15	//	短期版本 seat-v2：单价 180 分，2026-03-10 00:00 起替代旧版本，2026-03-20 00:00 结束
16	//	后续版本 seat-v3：单价 200 分，2026-03-20 00:00 至 2026-03-25 00:00，不填写替代来源
17	//
18	// 旧版本实际有效区间被截断到 3 月 10 日，短期版本占用到 3 月 20 日；
19	// 因此后续版本虽然落在旧版本“登记”的起止时间内，却不与任何仍实际有效的区间重叠。
20	var (
21		marchOldStart   = time.Date(2026, 3, 1, 0, 0, 0, 0, time.UTC)
22		marchOldEnd     = time.Date(2026, 3, 31, 0, 0, 0, 0, time.UTC)
23		marchShortStart = time.Date(2026, 3, 10, 0, 0, 0, 0, time.UTC)
24		marchShortEnd   = time.Date(2026, 3, 20, 0, 0, 0, 0, time.UTC)
25		marchFollowEnd  = time.Date(2026, 3, 25, 0, 0, 0, 0, time.UTC)
26	)
27	
28	// newMarchBook 登记旧版本与短期版本，形成“旧版实际止于 3 月 10 日、
29	// 短期版本占用到 3 月 20 日”的既有状态。
30	func newMarchBook(t *testing.T, start time.Time) (*Book, func(time.Time)) {
31		t.Helper()
32		now, setNow := fixedClock(start)
33		b := NewBook(WithClock(now))
34		oldEnd := marchOldEnd
35		if err := b.RegisterVersion(RegisterRequest{
36			ItemID: "seat", VersionID: "seat-v1", UnitPrice: 150,
37			Start: marchOldStart, End: &oldEnd,
38		}); err != nil {
39			t.Fatalf("register seat-v1: %v", err)
40		}
41		shortEnd := marchShortEnd
42		if err := b.RegisterVersion(RegisterRequest{
43			ItemID: "seat", VersionID: "seat-v2", UnitPrice: 180,
44			Start: marchShortStart, End: &shortEnd, Replaces: "seat-v1",
45		}); err != nil {
46			t.Fatalf("register seat-v2: %v", err)
47		}
48		return b, setNow
49	}
50	
51	// assertMarchBaseUnchanged 校验失败登记没有延长或恢复前两版的有效期，
52	// 也没有改写原来的替代关系。
53	func assertMarchBaseUnchanged(t *testing.T, b *Book) {
54		t.Helper()
55		views, err := b.ItemVersions("seat")
56		if err != nil {
57			t.Fatal(err)
58		}
59		if len(views) != 2 {
60			t.Fatalf("失败登记后应仍是两个版本，got %d", len(views))
61		}
62		old, short := views[0], views[1]
63		if old.VersionID != "seat-v1" || short.VersionID != "seat-v2" {
64			t.Fatalf("版本顺序异常: %q, %q", old.VersionID, short.VersionID)
65		}
66		if old.End == nil || !old.End.Equal(marchOldEnd) {
67			t.Fatalf("旧版登记结束被改写: %v", old.End)
68		}
69		if old.EffectiveEnd == nil || !old.EffectiveEnd.Equal(marchShortStart) {
70			t.Fatalf("旧版实际结束应仍是交接点 3 月 10 日: %v", old.EffectiveEnd)
71		}
72		if old.Replaces != "" || old.SupersededBy != "seat-v2" {
73			t.Fatalf("旧版替代关系被改写: Replaces=%q SupersededBy=%q", old.Replaces, old.SupersededBy)
74		}
75		if short.End == nil || !short.End.Equal(marchShortEnd) ||
76			short.EffectiveEnd == nil || !short.EffectiveEnd.Equal(marchShortEnd) {
77			t.Fatalf("短期版本边界被改写: 登记结束=%v 实际结束=%v", short.End, short.EffectiveEnd)
78		}
79		if short.Replaces != "seat-v1" || short.SupersededBy != "" {
80			t.Fatalf("短期版本替代关系被改写: Replaces=%q SupersededBy=%q",
81				short.Replaces, short.SupersededBy)
82		}
83	}
84	
85	// 提前到 3 月 19 日开始的后续登记与短期版本实际有效期重叠，必须返回现有的
86	// ErrOverlap；失败不留任何痕迹。把开始改到 3 月 20 日、沿用同一版本标识即可成功。
87	func TestFollowUpOverlapJudgedByEffectiveInterval(t *testing.T) {
88		b, _ := newMarchBook(t, marchShortStart)
89	
90		tooEarly := time.Date(2026, 3, 19, 0, 0, 0, 0, time.UTC)
91		failed := RegisterRequest{
92			ItemID: "seat", VersionID: "seat-v3", UnitPrice: 200,
93			Start: tooEarly, End: &marchFollowEnd,
94		}
95		if err := b.RegisterVersion(failed); !errors.Is(err, ErrOverlap) {
96			t.Fatalf("与短期版本实际有效期重叠应返回 ErrOverlap, got %v", err)
97		}
98	
99		// 失败后：前两版时间边界和替代关系与操作前一致，失败版本不在查询结果中。
100		assertMarchBaseUnchanged(t, b)
101	
102		// 开始改到 3 月 20 日零点（短期版本结束时刻，不含），沿用同一版本标识成功：
103		// 未成功的登记不能把标识当成已被占用。
104		if err := b.RegisterVersion(RegisterRequest{
105			ItemID: "seat", VersionID: "seat-v3", UnitPrice: 200,
106			Start: marchShortEnd, End: &marchFollowEnd,
107		}); err != nil {
108			t.Fatalf("相邻于实际有效区间的后续登记应成功: %v", err)
109		}
110	
111		views, err := b.ItemVersions("seat")
112		if err != nil {
113			t.Fatal(err)
114		}
115		if len(views) != 3 {
116			t.Fatalf("want 3 versions, got %d", len(views))
117		}
118		// 三个版本按生效时间排列。
119		got := []string{views[0].VersionID, views[1].VersionID, views[2].VersionID}
120		want := []string{"seat-v1", "seat-v2", "seat-v3"}
121		for i := range want {
122			if got[i] != want[i] {
123				t.Fatalf("版本顺序=%v, want %v", got, want)
124			}
125		}
126		old, short, follow := views[0], views[1], views[2]
127	
128		// 前两版边界与替代关系保持操作前状态：后续登记不能延长或恢复它们。
129		if old.End == nil || !old.End.Equal(marchOldEnd) {
130			t.Fatalf("旧版登记结束应仍是月底: %v", old.End)
131		}
132		if old.EffectiveEnd == nil || !old.EffectiveEnd.Equal(marchShortStart) {
133			t.Fatalf("旧版实际结束应仍是 3 月 10 日: %v", old.EffectiveEnd)
134		}
135		if old.SupersededBy != "seat-v2" {
136			t.Fatalf("旧版被替代关系: %q", old.SupersededBy)
137		}
138		if short.End == nil || !short.End.Equal(marchShortEnd) ||
139			short.EffectiveEnd == nil || !short.EffectiveEnd.Equal(marchShortEnd) {
140			t.Fatalf("短期版本结束应仍是 3 月 20 日: 登记=%v 实际=%v",
141				short.End, short.EffectiveEnd)
142		}
143		if short.Replaces != "seat-v1" {
144			t.Fatalf("短期版本替代来源: %q", short.Replaces)
145		}
146	
147		// 后续版本：未填写替代来源，实际区间即登记区间。
148		if follow.UnitPrice != 200 || follow.Replaces != "" || follow.SupersededBy != "" {
149			t.Fatalf("后续版本登记信息异常: %+v", follow)
150		}
151		if !follow.Start.Equal(marchShortEnd) {
152			t.Fatalf("后续版本开始: %v", follow.Start)
153		}
154		if follow.End == nil || !follow.End.Equal(marchFollowEnd) ||
155			follow.EffectiveEnd == nil || !follow.EffectiveEnd.Equal(marchFollowEnd) {
156			t.Fatalf("后续版本结束: 登记=%v 实际=%v, want 3 月 25 日",
157				follow.End, follow.EffectiveEnd)
158		}
159	}
160	
161	// 在短期版本结束时刻（不含）3 月 20 日零点报价：旧版本、短期版本都应以
162	// version_expired 拒绝，后续版本按 200 分确认。拒绝是正常受理，不返回错误，
163	// 金额为零，且保留调用者指定的费率项与版本，不自动切换。
164	func TestFollowUpBoundaryQuotesAtShortEnd(t *testing.T) {
165		b, setNow := newMarchBook(t, marchShortEnd)
166		if err := b.RegisterVersion(RegisterRequest{
167			ItemID: "seat", VersionID: "seat-v3", UnitPrice: 200,
168			Start: marchShortEnd, End: &marchFollowEnd,
169		}); err != nil {
170			t.Fatalf("register seat-v3: %v", err)
171		}
172	
173		setNow(marchShortEnd) // 2026-03-20 00:00：结束时刻不含在有效期内
174		cases := []struct {
175			name      string
176			requestID string
177			versionID string
178			confirmed bool
179			reason    RejectReason
180			unitPrice int64
181			total     int64
182		}{
183			{"旧版本已失效", "q-old-at-follow-start", "seat-v1", false, ReasonVersionExpired, 0, 0},
184			{"短期版本已失效", "q-short-at-follow-start", "seat-v2", false, ReasonVersionExpired, 0, 0},
185			{"后续版本确认", "q-follow-at-start", "seat-v3", true, ReasonNone, 200, 800},
186		}
187		for _, c := range cases {
188			req := QuoteRequest{
189				RequestID: c.requestID, ItemID: "seat",
190				VersionID: c.versionID, Quantity: 4,
191			}
192			out, err := b.Quote(req)
193			if err != nil {
194				t.Fatalf("%s: 拒绝/确认都是正常受理，err 应为空, got %v", c.name, err)
195			}
196			if out.Confirmed != c.confirmed {
197				t.Fatalf("%s: Confirmed=%v, want %v (%+v)", c.name, out.Confirmed, c.confirmed, out)
198			}
199			if out.Reason != c.reason {
200				t.Fatalf("%s: 原因=%q, want %q", c.name, out.Reason, c.reason)
201			}
202			if out.UnitPrice != c.unitPrice || out.Total != c.total {
203				t.Fatalf("%s: 单价/总价=%d/%d, want %d/%d",
204					c.name, out.UnitPrice, out.Total, c.unitPrice, c.total)
205			}
206			// 结果必须保留调用者指定的费率项、版本和数量，不能替调用者切换版本。
207			if out.Request != req {
208				t.Fatalf("%s: 请求来源未保留: %+v vs %+v", c.name, out.Request, req)
209			}
210			if !out.AcceptedAt.Equal(marchShortEnd) {
211				t.Fatalf("%s: 受理时刻=%v, want %v", c.name, out.AcceptedAt, marchShortEnd)
212			}
213		}
214	}
215	
216	// 后续版本自己的结束时刻 3 月 25 日零点同样不含在有效期内：此刻引用它应被拒绝。
217	func TestFollowUpExpiresAtOwnEnd(t *testing.T) {
218		b, setNow := newMarchBook(t, marchFollowEnd)
219		if err := b.RegisterVersion(RegisterRequest{
220			ItemID: "seat", VersionID: "seat-v3", UnitPrice: 200,
221			Start: marchShortEnd, End: &marchFollowEnd,
222		}); err != nil {
223			t.Fatalf("register seat-v3: %v", err)
224		}
225	
226		setNow(marchFollowEnd)
227		req := QuoteRequest{
228			RequestID: "q-follow-at-end", ItemID: "seat", VersionID: "seat-v3", Quantity: 4,
229		}
230		out, err := b.Quote(req)
231		if err != nil {
232			t.Fatalf("拒绝是正常受理，err 应为空: %v", err)
233		}
234		if out.Confirmed || out.Reason != ReasonVersionExpired {
235			t.Fatalf("结束时刻不含在有效期内，应 version_expired 拒绝: %+v", out)
236		}
237		if out.UnitPrice != 0 || out.Total != 0 {
238			t.Fatalf("拒绝结果单价/总价应为零: %d/%d", out.UnitPrice, out.Total)
239		}
240		if out.Request != req {
241			t.Fatalf("拒绝结果必须保留原请求来源: %+v vs %+v", out.Request, req)
242		}
243	}
