			if v.EffectiveEnd == nil || !v.EffectiveEnd.Equal(at(40)) {
				t.Fatalf("handoff point changed: %v", v.EffectiveEnd)
			}
		case "new":
			if v.End == nil || !v.End.Equal(at(60)) {
				t.Fatalf("new registered end changed: %v", v.End)
