1	package tariff
2	
3	import (
4		"errors"
5		"fmt"
6		"sync"
7		"testing"
8		"time"
9	)
10	
11	// 同一本尚未登记 seat 的账本，同时收到两份有效期重叠的登记时的并发回归测试。
12	//
13	// 两份登记都不填写替代来源，其余内容合法（全部为 UTC 零点，开始含、结束不含）：
14	//
15	//	v-a：单价 150 分，2026-03-01 起、2026-03-20 结束
16	//	v-b：单价 180 分，2026-03-10 起、2026-03-31 结束
17	//
18	// 两者在 2026-03-10 至 2026-03-20 之间重叠。测试保护既有规则：并发受理顺序
19	// 决定哪一版入库，但无论谁先抢到账本锁，都必须恰好一版成功、另一版返回可用
20	// errors.Is 识别的 ErrOverlap；不同版本标识不能绕过“同项有效期不得重叠”，
21	// 也不允许两份登记各自成功。失败登记不能覆盖成功方的任何字段，也不会占用
22	// 落败版本标识。
23	//
24	// 这里强调“同时发生”：两个 goroutine 经同一屏障一起进入 RegisterVersion，
25	// 而不是先顺序登记一版、再提交另一版。业务结论只依赖登记区间与受理时刻，
26	// 因此多轮重复执行、并把账本时钟注入到不同的运行日期（早于生效点、共同
27	// 有效当天、两版都结束之后），结论都一致，不依赖等待真实时间流逝。
28	
29	const (
30		corItemID   = "seat"
31		corVersionA = "v-a"
32		corVersionB = "v-b"
33		corRounds   = 12 // 每个运行日期下的并发轮数，提高两种受理顺序都被覆盖的机会
34	)
35	
36	var (
37		corVAStart    = time.Date(2026, 3, 1, 0, 0, 0, 0, time.UTC)
38		corVAEnd      = time.Date(2026, 3, 20, 0, 0, 0, 0, time.UTC)
39		corVBStart    = time.Date(2026, 3, 10, 0, 0, 0, 0, time.UTC)
40		corVBEnd      = time.Date(2026, 3, 31, 0, 0, 0, 0, time.UTC)
41		corCommonDay  = time.Date(2026, 3, 15, 0, 0, 0, 0, time.UTC) // 两版原计划共同有效的一天
42		corQuantity   = int64(4)
43		corRunOffsets = []time.Time{
44			time.Date(2025, 12, 31, 23, 0, 0, 0, time.UTC), // 远早于任一版本生效
45			time.Date(2026, 3, 1, 0, 0, 0, 0, time.UTC),    // 首版开始当天
46			corCommonDay, // 两版共同有效当天
47			time.Date(2026, 11, 11, 0, 0, 0, 0, time.UTC), // 两版都已结束之后
48		}
49	)
50	
51	// corCandidate 描述一份参与并发竞争的登记内容。
52	type corCandidate struct {
53		versionID string
54		unitPrice int64
55		start     time.Time
56		end       time.Time
57	}
58	
59	func corCandidates() (corCandidate, corCandidate) {
60		return corCandidate{
61				versionID: corVersionA,
62				unitPrice: 150,
63				start:     corVAStart,
64				end:       corVAEnd,
65			}, corCandidate{
66				versionID: corVersionB,
67				unitPrice: 180,
68				start:     corVBStart,
69				end:       corVBEnd,
70			}
71	}
72	
73	// corResult 记录某一份并发登记实际拿到的返回。
74	type corResult struct {
75		versionID string
76		err       error
77	}
78	
79	// corRegisterBoth 把两份登记同时发往同一本账本：goroutine 在同一屏障后一起
80	// 进入 RegisterVersion，制造对同一空费率项的真正并发；每份请求使用独立的
81	// 结束时刻副本，互不共享指针。调用方通过 first/second 控制发起顺序，
82	// 以便各轮交替两个版本的发起位置，让两种受理顺序都被实际走到；
83	// 返回值按版本标识归集，顺序本身不参与任何断言。
84	func corRegisterBoth(b *Book, first, second corCandidate) []corResult {
85		ordered := []corCandidate{first, second}
86		results := make([]corResult, 2)
87		start := make(chan struct{})
88		var wg sync.WaitGroup
89		for idx, cand := range ordered {
90			wg.Add(1)
91			go func(idx int, cand corCandidate) {
92				defer wg.Done()
93				<-start // 两份都就绪后一起进入登记
94				end := cand.end
95				err := b.RegisterVersion(RegisterRequest{
96					ItemID:    corItemID,
97					VersionID: cand.versionID,
98					UnitPrice: cand.unitPrice,
99					Start:     cand.start,
100					End:       &end, // Replaces 留空：两份登记都不填写替代来源
101				})
102				results[idx] = corResult{versionID: cand.versionID, err: err}
103			}(idx, cand)
104		}
105		close(start)
106		wg.Wait()
107		return results
108	}
109	
110	func corCandidateByID(t *testing.T, cands []corCandidate, id string) corCandidate {
111		t.Helper()
112		for _, c := range cands {
113			if c.versionID == id {
114				return c
115			}
116		}
117		t.Fatalf("未知候选版本 %q", id)
118		return corCandidate{}
119	}
120	
121	// corAssertExactlyOneWins 校验并发批次恰好一次成功、一次 ErrOverlap，
122	// 返回实际成功方与落败方的登记内容。两份各自成功、两份都失败或失败方拿到
123	// ErrOverlap 以外的错误，都视为破坏既有规则。
124	func corAssertExactlyOneWins(t *testing.T, results []corResult, cands []corCandidate) (corCandidate, corCandidate) {
125		t.Helper()
126		var success, rejected []corResult
127		for _, r := range results {
128			if r.err == nil {
129				success = append(success, r)
130				continue
131			}
132			if !errors.Is(r.err, ErrOverlap) {
133				t.Fatalf("版本 %s 并发登记落败时必须返回 ErrOverlap, got %v", r.versionID, r.err)
134			}
135			rejected = append(rejected, r)
136		}
137		if len(success) != 1 {
138			t.Fatalf("成功登记次数=%d，应恰好为 1（不能两版各自成功，也不能都失败）；结果: %+v",
139				len(success), results)
140		}
141		if len(rejected) != 1 {
142			t.Fatalf("ErrOverlap 次数=%d，应恰好为 1；结果: %+v", len(rejected), results)
143		}
144		winner := corCandidateByID(t, cands, success[0].versionID)
145		loser := corCandidateByID(t, cands, rejected[0].versionID)
146		if winner.versionID == loser.versionID {
147			t.Fatalf("成功方与落败方不应是同一版本: %q", winner.versionID)
148		}
149		return winner, loser
150	}
151	
152	// corAssertOnlyWinnerStored 校验 ItemVersions 只列出实际成功的那一版：
153	// 单价、登记起止、实际有效区间都与该请求一致，两种替代关系均为空，
154	// 结果中不能混入落败方的任何字段。
155	func corAssertOnlyWinnerStored(t *testing.T, b *Book, winner corCandidate) {
156		t.Helper()
157		views, err := b.ItemVersions(corItemID)
158		if err != nil {
159			t.Fatalf("查询成功登记版本: %v", err)
160		}
161		if len(views) != 1 {
162			t.Fatalf("并发登记后应只有一版入库，got %d: %+v", len(views), views)
163		}
164		v := views[0]
165		if v.ItemID != corItemID || v.VersionID != winner.versionID {
166			t.Fatalf("入库版本=%s/%s，want %s/%s（落败方不得残留）",
167				v.ItemID, v.VersionID, corItemID, winner.versionID)
168		}
169		if v.UnitPrice != winner.unitPrice {
170			t.Fatalf("入库单价=%d，want %d；失败登记不能覆盖成功方单价",
171				v.UnitPrice, winner.unitPrice)
172		}
173		if !v.Start.Equal(winner.start) || !v.EffectiveStart.Equal(winner.start) {
174			t.Fatalf("入库版本起点异常: 登记=%v 实际=%v, want %v",
175				v.Start, v.EffectiveStart, winner.start)
176		}
177		if v.End == nil || !v.End.Equal(winner.end) ||
178			v.EffectiveEnd == nil || !v.EffectiveEnd.Equal(winner.end) {
179			t.Fatalf("入库版本终点异常: 登记=%v 实际=%v, want %v",
180				v.End, v.EffectiveEnd, winner.end)
181		}
182		if v.Replaces != "" || v.SupersededBy != "" {
183			t.Fatalf("两份登记都未填写替代来源，入库版本两种替代关系应为空: Replaces=%q SupersededBy=%q",
184				v.Replaces, v.SupersededBy)
185		}
186	}
187	
188	// corAssertLoserLeftNoTrace 用落败方的同一内容再顺序提交一次：
189	// 仍应因区间重叠返回 ErrOverlap，而不是 ErrVersionExists 或成功——
190	// 失败的并发登记既没有把版本存进去，也没有占用落败版本标识。
191	func corAssertLoserLeftNoTrace(t *testing.T, b *Book, loser corCandidate) {
192		t.Helper()
193		end := loser.end
194		err := b.RegisterVersion(RegisterRequest{
195			ItemID: corItemID, VersionID: loser.versionID, UnitPrice: loser.unitPrice,
196			Start: loser.start, End: &end,
197		})
198		if !errors.Is(err, ErrOverlap) {
199			t.Fatalf("落败版本 %s 重提应仍为 ErrOverlap（标识未被占用、区间仍冲突）, got %v",
200				loser.versionID, err)
201		}
202	}
203	
204	// corAssertEffectiveVersionAtCommonDay 校验在两版原计划共同有效的 3 月 15 日，
205	// EffectiveVersionAt 必须选中实际成功方；同一瞬间换时区表示结论一致。
206	// 落败方在任何时刻都不得被选中：2 月 25 日两版都未生效；3 月 31 日两版区间
207	// 都已结束（结束时刻不含）；3 月 25 日只有当成功方是 v-b 时才可能选中 v-b。
208	func corAssertEffectiveVersionAtCommonDay(t *testing.T, b *Book, winner, loser corCandidate) {
209		t.Helper()
210	
211		view, err := b.EffectiveVersionAt(corItemID, corCommonDay)
212		if err != nil {
213			t.Fatalf("3 月 15 日应选中成功方 %s: %v", winner.versionID, err)
214		}
215		if view.VersionID != winner.versionID || view.UnitPrice != winner.unitPrice {
216			t.Fatalf("3 月 15 日选中 %s（%d 分），want %s（%d 分）",
217				view.VersionID, view.UnitPrice, winner.versionID, winner.unitPrice)
218		}
219	
220		// 同一瞬间的 +08:00 表示（3 月 15 日 08:00）必须得到同一个版本。
221		east := time.FixedZone("UTC+8", 8*3600)
222		sameInstant := time.Date(2026, 3, 15, 8, 0, 0, 0, east)
223		other, err := b.EffectiveVersionAt(corItemID, sameInstant)
224		if err != nil {
225			t.Fatalf("同一瞬间换时区表示也应选中成功方: %v", err)
226		}
227		if other.VersionID != winner.versionID {
228			t.Fatalf("同一瞬间不同时区表示选中了不同版本: %q vs %q",
229				other.VersionID, winner.versionID)
230		}
231	
232		// 早于任一版本开始（2 月 25 日）：无生效版本，不能补位。
233		if _, err := b.EffectiveVersionAt(corItemID, time.Date(2026, 2, 25, 0, 0, 0, 0, time.UTC)); !errors.Is(err, ErrNoEffectiveVersion) {
234			t.Fatalf("2 月 25 日应返回 ErrNoEffectiveVersion, got %v", err)
235		}
236		// 3 月 31 日零点：v-a 早已结束，v-b 的结束时刻也不含该点。
237		if _, err := b.EffectiveVersionAt(corItemID, corVBEnd); !errors.Is(err, ErrNoEffectiveVersion) {
238			t.Fatalf("3 月 31 日应返回 ErrNoEffectiveVersion, got %v", err)
239		}
240		// 3 月 25 日：成功方为 v-a 时已无生效版本；成功方为 v-b 时只能选中 v-b。
241		got, err := b.EffectiveVersionAt(corItemID, time.Date(2026, 3, 25, 0, 0, 0, 0, time.UTC))
242		switch winner.versionID {
243		case corVersionA:
244			if !errors.Is(err, ErrNoEffectiveVersion) {
245				t.Fatalf("v-a 成功时 3 月 25 日应无生效版本, got %+v (%v)", got, err)
246			}
247		case corVersionB:
248			if err != nil || got.VersionID != corVersionB {
249				t.Fatalf("v-b 成功时 3 月 25 日应仍选中 v-b, got %+v (%v)", got, err)
250			}
251		}
252		if got.VersionID == loser.versionID {
253			t.Fatalf("3 月 25 日选中了落败版本 %s", loser.versionID)
254		}
255	}
256	
257	// corAssertQuotesFollowWinner 把新报价的受理时刻设在 3 月 15 日，分别用
258	// 未使用过的请求标识引用两个版本，数量均为 4：成功方按其单价确认
259	// （150 分 → 600 分；180 分 → 720 分）并保留对应版本来源；落败方正常受理
260	// 但以 version_not_found 拒绝，单价与总价均为零，调用本身不返回错误。
261	func corAssertQuotesFollowWinner(t *testing.T, b *Book, winner, loser corCandidate, runLabel string, round int) {
262		t.Helper()
263		winReq := QuoteRequest{
264			RequestID: fmt.Sprintf("cor-quote-win-%s-%d", runLabel, round),
265			ItemID:    corItemID, VersionID: winner.versionID, Quantity: corQuantity,
266		}
267		winOut, err := b.Quote(winReq)
268		if err != nil {
269			t.Fatalf("引用成功方 %s 的报价是正常受理，err 应为空: %v", winner.versionID, err)
270		}
271		if !winOut.Confirmed {
272			t.Fatalf("引用成功方 %s 应确认, got %+v", winner.versionID, winOut)
273		}
274		if winOut.Reason != ReasonNone {
275			t.Fatalf("成功方确认结果不应带拒绝原因: %q", winOut.Reason)
276		}
277		if winOut.UnitPrice != winner.unitPrice {
278			t.Fatalf("成功方报价单价=%d，want %d", winOut.UnitPrice, winner.unitPrice)
279		}
280		wantTotal := winner.unitPrice * corQuantity // 150*4=600 或 180*4=720
281		if wantTotal != 600 && wantTotal != 720 {
282			t.Fatalf("测试数据总价应为 600 或 720, got %d", wantTotal)
283		}
284		if winOut.Total != wantTotal {
285			t.Fatalf("成功方报价总价=%d，want %d", winOut.Total, wantTotal)
286		}
287		if winOut.Request != winReq {
288			t.Fatalf("成功方报价来源必须保留原请求: %+v vs %+v", winOut.Request, winReq)
289		}
290		if !winOut.AcceptedAt.Equal(corCommonDay) {
291			t.Fatalf("成功方受理时刻=%v，want %v", winOut.AcceptedAt, corCommonDay)
292		}
293	
294		loseReq := QuoteRequest{
295			RequestID: fmt.Sprintf("cor-quote-lose-%s-%d", runLabel, round),
296			ItemID:    corItemID, VersionID: loser.versionID, Quantity: corQuantity,
297		}
298		loseOut, err := b.Quote(loseReq)
299		if err != nil {
300			t.Fatalf("引用落败方 %s 的拒绝也是正常受理，调用不应返回错误, got %v", loser.versionID, err)
301		}
302		if loseOut.Confirmed {
303			t.Fatalf("落败版本未入库，不能确认报价: %+v", loseOut)
304		}
305		if loseOut.Reason != ReasonVersionNotFound {
306			t.Fatalf("落败版本报价原因=%q，want %q", loseOut.Reason, ReasonVersionNotFound)
307		}
308		if loseOut.UnitPrice != 0 || loseOut.Total != 0 {
309			t.Fatalf("落败版本报价单价/总价应均为零: %d/%d", loseOut.UnitPrice, loseOut.Total)
310		}
311		if loseOut.Request != loseReq {
312			t.Fatalf("拒绝结果必须保留调用方指定的落败版本来源: %+v vs %+v", loseOut.Request, loseReq)
313		}
314		if !loseOut.AcceptedAt.Equal(corCommonDay) {
315			t.Fatalf("落败方受理时刻=%v，want %v", loseOut.AcceptedAt, corCommonDay)
316		}
317	
318		// 首次受理结果各自按请求标识保存，查询结论与本次实际受理一致。
319		storedWin, err := b.Lookup(winReq.RequestID)
320		if err != nil || storedWin != winOut {
321			t.Fatalf("成功方报价未按标识保存: %+v (%v)", storedWin, err)
322		}
323		storedLose, err := b.Lookup(loseReq.RequestID)
324		if err != nil || storedLose != loseOut {
325			t.Fatalf("落败方拒绝未按标识保存: %+v (%v)", storedLose, err)
326		}
327	}
328	
329	// TestConcurrentOverlappingRegistrationSingleVersionStored：空账本同时接收
330	// v-a、v-b 两份有效期重叠的登记，保护“同一项同时刻至多一版入库”的既有规则。
331	// 哪一版成功由实际受理顺序决定，测试不断言固定获胜方，但对任一获胜结果都
332	// 完整校验登记视图、时刻选版与两条报价结论；多轮执行并注入不同运行日期，
333	// 业务结论必须相同。
334	func TestConcurrentOverlappingRegistrationSingleVersionStored(t *testing.T) {
335		allCands := []corCandidate{}
336		a, c := corCandidates()
337		allCands = append(allCands, a, c)
338	
339		winners := map[string]int{}
340		for _, runDate := range corRunOffsets {
341			runLabel := runDate.Format("2006-01-02")
342			t.Run("rundate-"+runLabel, func(t *testing.T) {
343				for round := 0; round < corRounds; round++ {
344					t.Run(fmt.Sprintf("round-%d", round), func(t *testing.T) {
345						// 账本时钟被固定在某个“运行日期”上：登记不看时钟，
346						// 报价受理时刻随后显式设到 3 月 15 日，无需等待真实时间。
347						now, setNow := fixedClock(runDate)
348						b := NewBook(WithClock(now))
349	
350						// 两个 goroutine 经屏障同时放行；逐轮交替发起位置只是让两种
351						// 受理顺序都有机会被实际走到，不断言哪一版必然获胜。
352						first, second := a, c
353						if round%2 == 1 {
354							first, second = c, a
355						}
356						results := corRegisterBoth(b, first, second)
357						winner, loser := corAssertExactlyOneWins(t, results, allCands)
358						winners[winner.versionID]++
359	
360						corAssertOnlyWinnerStored(t, b, winner)
361						corAssertLoserLeftNoTrace(t, b, loser)
362						corAssertEffectiveVersionAtCommonDay(t, b, winner, loser)
363	
364						// 新报价的受理时刻统一设在两版原计划共同有效的 3 月 15 日。
365						setNow(corCommonDay)
366						corAssertQuotesFollowWinner(t, b, winner, loser, runLabel, round)
367					})
368				}
369			})
370		}
371		t.Logf("各轮实际受理成功方分布: %v（v-a 与 v-b 都允许先入库，测试只要求恰好一版）", winners)
372	}
373

